private theorem block_data (depth node size j q a : Nat) (s t : Bool)
    (hm : .variable j s q a ∈ block depth t node size) :
    j = depth ∧ s = t ∧ q = node

private theorem siblings_ordered (rem depth node : Nat) (x y : Position)
    (hx : x ∈ tree true rem (depth + 1) (2 * node))
    (hy : y ∈ tree true rem (depth + 1) (2 * node + 1)) : MinusParentOrdered x y

private theorem children_disjoint (column : Bool) (rem depth node : Nat) (x : Position)
    (h0 : x ∈ tree column rem (depth + 1) (2 * node))
    (h1 : x ∈ tree column rem (depth + 1) (2 * node + 1)) : False

private theorem constant_phase_pairwise (column : Bool) (xs : List Position) (k : Nat)
    (hk : ∀ x ∈ xs, phase column x = k) :
    xs.Pairwise (fun x y => phase column x ≤ phase column y)

private theorem phase_pairwise_append (column : Bool) (xs ys : List Position) (a b : Nat)
    (ha : ∀ x ∈ xs, phase column x = a) (hb : ∀ y ∈ ys, phase column y = b)
    (hab : a ≤ b) : (xs ++ ys).Pairwise (fun x y => phase column x ≤ phase column y)

private theorem selected_ra {h : Nat} (s : PathSelection h) (l k g : Nat)
    (hl : 1 ≤ l) (hlh : l ≤ h) (hk : k < 6) (hg : g < 2) :
    s.Selected false (s.ra l k g)

private theorem selected_ca {h : Nat} (s : PathSelection h) (l k g : Nat)
    (hl : 1 ≤ l) (hlh : l ≤ h) (hk : k < 6) (hg : g < 2) :
    s.Selected true (s.ca l k g)
